package com.example.a2hauto;

import android.os.Bundle;
import android.util.Log;
import android.view.View;
import android.widget.ProgressBar;
import android.widget.Toast;

import androidx.activity.EdgeToEdge;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.graphics.Insets;
import androidx.core.view.ViewCompat;
import androidx.core.view.WindowInsetsCompat;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.example.a2hauto.adapter.VehicleAdapter;
import com.example.a2hauto.api.ApiService;
import com.example.a2hauto.model.ApiResponse;
import com.example.a2hauto.model.Listing;

import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

import retrofit2.Call;
import retrofit2.Callback;
import retrofit2.Response;
import retrofit2.Retrofit;
import retrofit2.converter.gson.GsonConverterFactory;

public class MainActivity extends AppCompatActivity {

    private static final String TAG = "MainActivity";
    private RecyclerView rvVehicles;
    private VehicleAdapter adapter;
    private ProgressBar progressBar;
    private ApiService apiService;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        EdgeToEdge.enable(this);
        setContentView(R.layout.activity_main);
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main), (v, insets) -> {
            Insets systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars());
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom);
            return insets;
        });

        rvVehicles = findViewById(R.id.rvVehicles);
        progressBar = findViewById(R.id.progressBar);

        rvVehicles.setLayoutManager(new LinearLayoutManager(this));
        adapter = new VehicleAdapter(new ArrayList<>());
        rvVehicles.setAdapter(adapter);

        initRetrofit();
        fetchListings();
    }

    private void initRetrofit() {
        Retrofit retrofit = new Retrofit.Builder()
                .baseUrl("http://vehiclemarket.runasp.net/")
                .addConverterFactory(GsonConverterFactory.create())
                .build();

        apiService = retrofit.create(ApiService.class);
    }

    private void fetchListings() {
        progressBar.setVisibility(View.VISIBLE);
        apiService.getListings().enqueue(new Callback<ApiResponse<List<Listing>>>() {
            @Override
            public void onResponse(Call<ApiResponse<List<Listing>>> call, Response<ApiResponse<List<Listing>>> response) {
                progressBar.setVisibility(View.GONE);
                if (response.isSuccessful() && response.body() != null) {
                    ApiResponse<List<Listing>> apiResponse = response.body();
                    if (apiResponse.isSuccess() && apiResponse.getData() != null) {
                        // Filter listings with status "Active"
                        List<Listing> activeListings = apiResponse.getData().stream()
                                .filter(listing -> "Active".equalsIgnoreCase(listing.getStatus()))
                                .collect(Collectors.toList());

                        adapter.setListings(activeListings);

                        if (activeListings.isEmpty()) {
                            Toast.makeText(MainActivity.this, "Hiện không có bài đăng nào đang hoạt động", Toast.LENGTH_SHORT).show();
                        }
                    } else {
                        Toast.makeText(MainActivity.this, apiResponse.getMessage(), Toast.LENGTH_SHORT).show();
                    }
                } else {
                    Log.e(TAG, "Error: " + response.code());
                    Toast.makeText(MainActivity.this, "Không thể tải dữ liệu", Toast.LENGTH_SHORT).show();
                }
            }

            @Override
            public void onFailure(Call<ApiResponse<List<Listing>>> call, Throwable t) {
                progressBar.setVisibility(View.GONE);
                Log.e(TAG, "Failure: " + t.getMessage());
                Toast.makeText(MainActivity.this, "Lỗi kết nối: " + t.getMessage(), Toast.LENGTH_SHORT).show();
            }
        });
    }
}

package com.example.a2hauto;

import android.os.Bundle;
import android.util.Log;
import android.view.View;
import android.widget.ProgressBar;
import android.widget.TextView;
import android.widget.Toast;

import androidx.activity.EdgeToEdge;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.graphics.Insets;
import androidx.core.view.ViewCompat;
import androidx.core.view.WindowInsetsCompat;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.example.a2hauto.adapter.VehicleAdapter;
import com.example.a2hauto.api.ApiClient;
import com.example.a2hauto.api.ApiService;
import com.example.a2hauto.auth.AuthSessionManager;
import com.example.a2hauto.auth.LoginDialogFragment;
import com.example.a2hauto.auth.RegisterDialogFragment;
import com.example.a2hauto.model.ApiResponse;
import com.example.a2hauto.model.Listing;
import com.google.android.material.appbar.AppBarLayout;
import com.google.android.material.dialog.MaterialAlertDialogBuilder;

import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

import retrofit2.Call;
import retrofit2.Callback;
import retrofit2.Response;

public class MainActivity extends AppCompatActivity implements LoginDialogFragment.LoginDialogListener, RegisterDialogFragment.RegisterDialogListener {

    private static final String TAG = "MainActivity";
    private static final float MINI_HEADER_FADE_START = 0.38f;
    private static final float MINI_HEADER_FADE_END = 0.72f;
    private RecyclerView rvVehicles;
    private VehicleAdapter adapter;
    private ProgressBar progressBar;
    private TextView tvListingCount;
    private TextView tvMiniListingCount;
    private TextView tvSectionSubtitle;
    private TextView tvEmptyState;
    private View miniHeaderCard;
    private AppBarLayout appBarLayout;
    private boolean isMiniHeaderVisible;
    private AuthSessionManager authSessionManager;
    private ApiService apiService;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        EdgeToEdge.enable(this);
        setContentView(R.layout.activity_main);
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main), (v, insets) -> {
            Insets systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars());
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom);
            return insets;
        });

        rvVehicles = findViewById(R.id.rvVehicles);
        progressBar = findViewById(R.id.progressBar);
        tvListingCount = findViewById(R.id.tvListingCount);
        tvMiniListingCount = findViewById(R.id.tvMiniListingCount);
        tvSectionSubtitle = findViewById(R.id.tvSectionSubtitle);
        tvEmptyState = findViewById(R.id.tvEmptyState);
        miniHeaderCard = findViewById(R.id.miniHeaderCard);
        appBarLayout = findViewById(R.id.appBarLayout);
        authSessionManager = new AuthSessionManager(this);

        rvVehicles.setLayoutManager(new LinearLayoutManager(this));
        rvVehicles.setHasFixedSize(true);
        adapter = new VehicleAdapter(new ArrayList<>());
        rvVehicles.setAdapter(adapter);

        setupActions();
        setupMiniHeaderBehavior();
        initRetrofit();
        fetchListings();
    }

    private void setupActions() {
        findViewById(R.id.btnMenu).setOnClickListener(v -> showComingSoon(getString(R.string.menu)));
        findViewById(R.id.btnHeaderFavorite).setOnClickListener(v -> showComingSoon(getString(R.string.nav_favorites)));
        findViewById(R.id.btnMiniMenu).setOnClickListener(v -> showComingSoon(getString(R.string.menu)));
        findViewById(R.id.btnMiniFavorite).setOnClickListener(v -> showComingSoon(getString(R.string.nav_favorites)));
        findViewById(R.id.miniSearchBar).setOnClickListener(v -> showComingSoon(getString(R.string.search_hint)));
        findViewById(R.id.navHome).setOnClickListener(v -> rvVehicles.smoothScrollToPosition(0));
        findViewById(R.id.navFavorites).setOnClickListener(v -> showComingSoon(getString(R.string.nav_favorites)));
        findViewById(R.id.navAccount).setOnClickListener(v -> handleAccountAction());
    }

    private void setupMiniHeaderBehavior() {
        updateMiniHeaderProgress(0f);
        appBarLayout.addOnOffsetChangedListener((appBarLayout, verticalOffset) -> {
            if (appBarLayout.getTotalScrollRange() == 0) {
                return;
            }

            float collapseRatio = Math.abs(verticalOffset) / (float) appBarLayout.getTotalScrollRange();
            float progress = (collapseRatio - MINI_HEADER_FADE_START) / (MINI_HEADER_FADE_END - MINI_HEADER_FADE_START);
            updateMiniHeaderProgress(Math.max(0f, Math.min(1f, progress)));
        });
    }

    private void updateMiniHeaderProgress(float progress) {
        miniHeaderCard.animate().cancel();

        isMiniHeaderVisible = progress > 0.01f;
        miniHeaderCard.setVisibility(isMiniHeaderVisible ? View.VISIBLE : View.INVISIBLE);
        miniHeaderCard.setAlpha(progress);
        miniHeaderCard.setTranslationY((1f - progress) * -20f);
    }

    private void handleAccountAction() {
        if (authSessionManager.isLoggedIn()) {
            showAccountDialog();
            return;
        }

        showLoginDialog();
    }

    private void showLoginDialog() {
        if (getSupportFragmentManager().findFragmentByTag(LoginDialogFragment.TAG) == null) {
            new LoginDialogFragment().show(getSupportFragmentManager(), LoginDialogFragment.TAG);
        }
    }

    private void showRegisterDialog() {
        if (getSupportFragmentManager().findFragmentByTag(RegisterDialogFragment.TAG) == null) {
            new RegisterDialogFragment().show(getSupportFragmentManager(), RegisterDialogFragment.TAG);
        }
    }

    private void showAccountDialog() {
        new MaterialAlertDialogBuilder(this)
                .setTitle(R.string.account_dialog_title)
                .setMessage(getString(
                        R.string.account_dialog_message,
                        authSessionManager.getDisplayName(),
                        authSessionManager.getPhoneNumber()
                ))
                .setNegativeButton(android.R.string.cancel, null)
                .setPositiveButton(R.string.action_logout, (dialog, which) -> {
                    authSessionManager.logout();
                    Toast.makeText(this, R.string.logout_success, Toast.LENGTH_SHORT).show();
                })
                .show();
    }

    private void showComingSoon(String featureName) {
        Toast.makeText(this, getString(R.string.coming_soon, featureName), Toast.LENGTH_SHORT).show();
    }

    private void initRetrofit() {
        apiService = ApiClient.getApiService();
    }

    private void fetchListings() {
        progressBar.setVisibility(View.VISIBLE);
        tvEmptyState.setVisibility(View.GONE);
        apiService.getListings().enqueue(new Callback<ApiResponse<List<Listing>>>() {
            @Override
            public void onResponse(Call<ApiResponse<List<Listing>>> call, Response<ApiResponse<List<Listing>>> response) {
                progressBar.setVisibility(View.GONE);
                if (response.isSuccessful() && response.body() != null) {
                    ApiResponse<List<Listing>> apiResponse = response.body();
                    if (apiResponse.isSuccess() && apiResponse.getData() != null) {
                        // Filter listings with status "Active"
                        List<Listing> activeListings = apiResponse.getData().stream()
                                .filter(listing -> "Active".equalsIgnoreCase(listing.getStatus()))
                                .collect(Collectors.toList());

                        updateListingUi(activeListings);

                        if (activeListings.isEmpty()) {
                            Toast.makeText(MainActivity.this, "Hiện không có bài đăng nào đang hoạt động", Toast.LENGTH_SHORT).show();
                        }
                    } else {
                        updateListingUi(new ArrayList<>());
                        Toast.makeText(MainActivity.this, apiResponse.getMessage(), Toast.LENGTH_SHORT).show();
                    }
                } else {
                    updateListingUi(new ArrayList<>());
                    Log.e(TAG, "Error: " + response.code());
                    Toast.makeText(MainActivity.this, "Không thể tải dữ liệu", Toast.LENGTH_SHORT).show();
                }
            }

            @Override
            public void onFailure(Call<ApiResponse<List<Listing>>> call, Throwable t) {
                progressBar.setVisibility(View.GONE);
                updateListingUi(new ArrayList<>());
                Log.e(TAG, "Failure: " + t.getMessage());
                Toast.makeText(MainActivity.this, "Lỗi kết nối: " + t.getMessage(), Toast.LENGTH_SHORT).show();
            }
        });
    }

    private void updateListingUi(List<Listing> activeListings) {
        adapter.setListings(activeListings);
        tvListingCount.setText(getString(R.string.listing_count_format, activeListings.size()));
        tvMiniListingCount.setText(getString(R.string.listing_count_format, activeListings.size()));
        tvSectionSubtitle.setText(getString(R.string.featured_section_subtitle));

        boolean isEmpty = activeListings.isEmpty();
        tvEmptyState.setVisibility(isEmpty ? View.VISIBLE : View.GONE);
        rvVehicles.setVisibility(isEmpty ? View.INVISIBLE : View.VISIBLE);

    }

    @Override
    public void onLoginSuccess(String displayName) {
        // Auth dialog already shows success feedback.
    }

    @Override
    public void onOpenRegisterRequested() {
        showRegisterDialog();
    }

    @Override
    public void onRegisterSuccess(String displayName) {
        // Auth dialog already shows success feedback.
    }

    @Override
    public void onOpenLoginRequested() {
        showLoginDialog();
    }
}

package com.example.a2hauto.api;

import retrofit2.Retrofit;
import retrofit2.converter.gson.GsonConverterFactory;

public final class ApiClient {

    public static final String BASE_URL = "http://vehiclemarket.runasp.net/";
    private static Retrofit retrofit;

    private ApiClient() {
    }

    public static ApiService getApiService() {
        if (retrofit == null) {
            retrofit = new Retrofit.Builder()
                    .baseUrl(BASE_URL)
                    .addConverterFactory(GsonConverterFactory.create())
                    .build();
        }
        return retrofit.create(ApiService.class);
    }
}

package com.example.a2hauto.auth;

import android.content.Context;
import android.content.SharedPreferences;
import android.text.TextUtils;

import com.example.a2hauto.R;

public class AuthSessionManager {

    private static final String PREFS_NAME = "a2h_auto_auth";
    private static final String KEY_IS_LOGGED_IN = "is_logged_in";
    private static final String KEY_FULL_NAME = "full_name";
    private static final String KEY_PHONE = "phone";
    private static final String KEY_AUTH_TOKEN = "auth_token";
    private static final String KEY_PENDING_FULL_NAME = "pending_full_name";
    private static final String KEY_PENDING_PHONE = "pending_phone";

    private final SharedPreferences sharedPreferences;
    private final Context appContext;

    public AuthSessionManager(Context context) {
        appContext = context.getApplicationContext();
        sharedPreferences = appContext.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE);
    }

    public boolean isLoggedIn() {
        return sharedPreferences.getBoolean(KEY_IS_LOGGED_IN, false)
                && !TextUtils.isEmpty(sharedPreferences.getString(KEY_PHONE, ""));
    }

    public void saveSession(String fullName, String phone, String authToken) {
        String sanitizedName = fullName == null ? "" : fullName.trim();
        String normalizedPhone = AuthValidator.normalizePhone(phone);
        sharedPreferences.edit()
                .putString(KEY_FULL_NAME, sanitizedName)
                .putString(KEY_PHONE, normalizedPhone)
                .putString(KEY_AUTH_TOKEN, authToken == null ? "" : authToken)
                .remove(KEY_PENDING_FULL_NAME)
                .remove(KEY_PENDING_PHONE)
                .putBoolean(KEY_IS_LOGGED_IN, true)
                .apply();
    }

    public void savePendingRegistration(String fullName, String phone) {
        sharedPreferences.edit()
                .putString(KEY_PENDING_FULL_NAME, fullName == null ? "" : fullName.trim())
                .putString(KEY_PENDING_PHONE, AuthValidator.normalizePhone(phone))
                .putBoolean(KEY_IS_LOGGED_IN, false)
                .apply();
    }

    public void logout() {
        sharedPreferences.edit().clear().apply();
    }

    public String getDisplayName() {
        String displayName = sharedPreferences.getString(KEY_FULL_NAME, "");
        if (TextUtils.isEmpty(displayName)) {
            String phoneNumber = getPhoneNumber();
            if (!TextUtils.isEmpty(phoneNumber)) {
                return phoneNumber;
            }
            return appContext.getString(R.string.account_guest_name);
        }
        return displayName;
    }

    public String getPhoneNumber() {
        return sharedPreferences.getString(KEY_PHONE, "");
    }

    public String getAuthToken() {
        return sharedPreferences.getString(KEY_AUTH_TOKEN, "");
    }

    public String getPendingFullName() {
        return sharedPreferences.getString(KEY_PENDING_FULL_NAME, "");
    }

    public String getPendingPhoneNumber() {
        return sharedPreferences.getString(KEY_PENDING_PHONE, "");
    }

    public void clearPendingRegistration() {
        sharedPreferences.edit()
                .remove(KEY_PENDING_FULL_NAME)
                .remove(KEY_PENDING_PHONE)
                .apply();
    }
}

package com.example.a2hauto.auth;

public final class AuthValidator {

    private AuthValidator() {
    }

    public static String normalizePhone(String phone) {
        if (phone == null) {
            return "";
        }
        return phone.replaceAll("\\s+", "").trim();
    }

    public static boolean isValidPhone(String phone) {
        return normalizePhone(phone).matches("^\\d{9,11}$");
    }

    public static boolean isValidFullName(String fullName) {
        return fullName != null && fullName.trim().length() >= 2;
    }

    public static boolean isValidPassword(String password) {
        if (password == null || password.isEmpty()) {
            return false;
        }

        if (password.length() < 8 || password.length() > 32) {
            return false;
        }

        boolean hasUppercase = false;
        boolean hasLowercase = false;
        boolean hasDigit = false;

        for (char character : password.toCharArray()) {
            if (Character.isUpperCase(character)) {
                hasUppercase = true;
            } else if (Character.isLowerCase(character)) {
                hasLowercase = true;
            } else if (Character.isDigit(character)) {
                hasDigit = true;
            }
        }

        return hasUppercase && hasLowercase && hasDigit;
    }
}

package com.example.a2hauto.auth;

import android.app.Dialog;
import android.graphics.Color;
import android.graphics.drawable.ColorDrawable;
import android.os.Bundle;
import android.text.Editable;
import android.text.TextUtils;
import android.text.TextWatcher;
import android.view.LayoutInflater;
import android.view.View;
import android.view.Window;
import android.view.WindowManager;
import android.widget.FrameLayout;
import android.widget.ImageButton;
import android.widget.TextView;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.fragment.app.DialogFragment;

import com.example.a2hauto.R;
import com.google.android.material.button.MaterialButton;
import com.google.android.material.card.MaterialCardView;
import com.google.android.material.textfield.TextInputEditText;
import com.google.android.material.textfield.TextInputLayout;

public class LoginDialogFragment extends DialogFragment {

    public interface LoginDialogListener {
        void onLoginSuccess(String displayName);

        void onOpenRegisterRequested();
    }

    public static final String TAG = "LoginDialogFragment";

    private AuthSessionManager authSessionManager;
    private AuthRepository authRepository;
    private TextInputLayout tilPhone;
    private TextInputLayout tilPassword;
    private TextInputEditText etPhone;
    private TextInputEditText etPassword;
    private MaterialButton btnLogin;
    private View contentView;
    private ImageButton btnClose;
    private TextView tvForgotPassword;
    private TextView tvOpenRegister;
    private MaterialCardView cardGoogleLogin;

    @NonNull
    @Override
    public Dialog onCreateDialog(@Nullable Bundle savedInstanceState) {
        authSessionManager = new AuthSessionManager(requireContext());
        authRepository = new AuthRepository();

        FrameLayout container = new FrameLayout(requireContext());
        View view = getLayoutInflater().inflate(R.layout.dialog_login, container, false);
        contentView = view;
        bindViews(view);
        setupActions();
        prefillPendingRegistrationData();
        updateLoginButtonState();

        Dialog dialog = new Dialog(requireContext());
        dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);
        dialog.setContentView(view);
        dialog.setCancelable(true);
        dialog.setCanceledOnTouchOutside(true);
        return dialog;
    }

    @Override
    public void onStart() {
        super.onStart();
        Dialog dialog = getDialog();
        if (dialog != null && dialog.getWindow() != null) {
            Window window = dialog.getWindow();
            window.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));
            int width = (int) (requireContext().getResources().getDisplayMetrics().widthPixels * 0.94f);
            window.setLayout(width, WindowManager.LayoutParams.WRAP_CONTENT);
        }
    }

    private void bindViews(View view) {
        btnClose = view.findViewById(R.id.btnCloseLoginDialog);
        tilPhone = view.findViewById(R.id.tilLoginPhone);
        tilPassword = view.findViewById(R.id.tilLoginPassword);
        etPhone = view.findViewById(R.id.etLoginPhone);
        etPassword = view.findViewById(R.id.etLoginPassword);
        btnLogin = view.findViewById(R.id.btnLogin);
        tvForgotPassword = view.findViewById(R.id.tvForgotPassword);
        tvOpenRegister = view.findViewById(R.id.tvOpenRegister);
        cardGoogleLogin = view.findViewById(R.id.cardGoogleLogin);
    }

    private void setupActions() {
        btnClose.setOnClickListener(v -> dismiss());
        tvForgotPassword.setOnClickListener(v -> Toast.makeText(requireContext(), R.string.forgot_password_placeholder, Toast.LENGTH_SHORT).show());
        cardGoogleLogin.setOnClickListener(v -> Toast.makeText(requireContext(), R.string.google_login_placeholder, Toast.LENGTH_SHORT).show());
        tvOpenRegister.setOnClickListener(v -> {
            dismiss();
            if (getActivity() instanceof LoginDialogListener) {
                ((LoginDialogListener) getActivity()).onOpenRegisterRequested();
            }
        });

        btnLogin.setOnClickListener(v -> attemptLogin());

        TextWatcher textWatcher = new TextWatcher() {
            @Override
            public void beforeTextChanged(CharSequence s, int start, int count, int after) {
            }

            @Override
            public void onTextChanged(CharSequence s, int start, int before, int count) {
                clearErrors();
                updateLoginButtonState();
            }

            @Override
            public void afterTextChanged(Editable s) {
            }
        };

        etPhone.addTextChangedListener(textWatcher);
        etPassword.addTextChangedListener(textWatcher);
    }

    private void attemptLogin() {
        String phone = getText(etPhone);
        String password = getText(etPassword);
        boolean isValid = true;
        View firstInvalidField = null;

        clearErrors();

        if (!AuthValidator.isValidPhone(phone)) {
            tilPhone.setError(getString(R.string.validation_phone_required));
            isValid = false;
            firstInvalidField = etPhone;
        }

        if (password.isEmpty()) {
            tilPassword.setError(getString(R.string.validation_password_required));
            isValid = false;
            if (firstInvalidField == null) {
                firstInvalidField = etPassword;
            }
        }

        if (!isValid) {
            if (firstInvalidField != null) {
                firstInvalidField.requestFocus();
            }
            return;
        }

        setLoading(true);
        authRepository.login(phone, password, new AuthRepository.AuthCallback() {
            @Override
            public void onSuccess(String token, String message) {
                if (!isAdded()) {
                    return;
                }

                String displayName = resolveDisplayNameAfterLogin(phone, token);
                authSessionManager.saveSession(displayName, phone, token);
                displayName = authSessionManager.getDisplayName();
                Toast.makeText(requireContext(), getString(R.string.login_success, displayName), Toast.LENGTH_SHORT).show();
                if (getActivity() instanceof LoginDialogListener) {
                    ((LoginDialogListener) getActivity()).onLoginSuccess(displayName);
                }
                dismissAllowingStateLoss();
            }

            @Override
            public void onError(String message) {
                if (!isAdded()) {
                    return;
                }

                setLoading(false);
                tilPassword.setError(message);
                Toast.makeText(requireContext(), message, Toast.LENGTH_SHORT).show();
            }
        });
    }

    private void clearErrors() {
        tilPhone.setError(null);
        tilPassword.setError(null);
    }

    private void updateLoginButtonState() {
        btnLogin.setEnabled(true);
    }

    private void prefillPendingRegistrationData() {
        String pendingPhone = authSessionManager.getPendingPhoneNumber();
        if (!TextUtils.isEmpty(pendingPhone) && TextUtils.isEmpty(getText(etPhone))) {
            etPhone.setText(pendingPhone);
            etPhone.setSelection(pendingPhone.length());
        }
    }

    private String resolveDisplayNameAfterLogin(String phone, String token) {
        String displayNameFromToken = JwtUtils.extractDisplayName(token);
        if (!TextUtils.isEmpty(displayNameFromToken)) {
            return displayNameFromToken;
        }

        String normalizedPhone = AuthValidator.normalizePhone(phone);
        String pendingPhone = authSessionManager.getPendingPhoneNumber();
        String pendingFullName = authSessionManager.getPendingFullName();
        if (!TextUtils.isEmpty(pendingFullName) && normalizedPhone.equals(pendingPhone)) {
            return pendingFullName;
        }

        return "";
    }

    private void setLoading(boolean isLoading) {
        if (contentView != null) {
            contentView.setEnabled(!isLoading);
        }
        btnClose.setEnabled(!isLoading);
        etPhone.setEnabled(!isLoading);
        etPassword.setEnabled(!isLoading);
        tvForgotPassword.setEnabled(!isLoading);
        tvOpenRegister.setEnabled(!isLoading);
        cardGoogleLogin.setEnabled(!isLoading);
        btnLogin.setEnabled(!isLoading);
        btnLogin.setText(isLoading ? R.string.action_logging_in : R.string.action_login);
        Dialog dialog = getDialog();
        if (dialog != null) {
            dialog.setCancelable(!isLoading);
            dialog.setCanceledOnTouchOutside(!isLoading);
        }
    }

    private String getText(TextInputEditText editText) {
        return editText.getText() == null ? "" : editText.getText().toString().trim();
    }
}

package com.example.a2hauto.auth;

import android.app.Dialog;
import android.graphics.Color;
import android.graphics.drawable.ColorDrawable;
import android.os.Bundle;
import android.text.Editable;
import android.text.TextWatcher;
import android.view.LayoutInflater;
import android.view.View;
import android.view.Window;
import android.view.WindowManager;
import android.widget.FrameLayout;
import android.widget.ImageButton;
import android.widget.TextView;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.fragment.app.DialogFragment;

import com.example.a2hauto.R;
import com.google.android.material.button.MaterialButton;
import com.google.android.material.textfield.TextInputEditText;
import com.google.android.material.textfield.TextInputLayout;

public class RegisterDialogFragment extends DialogFragment {

    public interface RegisterDialogListener {
        void onRegisterSuccess(String displayName);

        void onOpenLoginRequested();
    }

    public static final String TAG = "RegisterDialogFragment";

    private AuthSessionManager authSessionManager;
    private AuthRepository authRepository;
    private TextInputLayout tilName;
    private TextInputLayout tilPhone;
    private TextInputLayout tilPassword;
    private TextInputEditText etName;
    private TextInputEditText etPhone;
    private TextInputEditText etPassword;
    private MaterialButton btnRegister;
    private View contentView;
    private ImageButton btnClose;
    private TextView tvOpenLogin;

    @NonNull
    @Override
    public Dialog onCreateDialog(@Nullable Bundle savedInstanceState) {
        authSessionManager = new AuthSessionManager(requireContext());
        authRepository = new AuthRepository();

        FrameLayout container = new FrameLayout(requireContext());
        View view = getLayoutInflater().inflate(R.layout.dialog_register, container, false);
        contentView = view;
        bindViews(view);
        setupActions();
        updateRegisterButtonState();

        Dialog dialog = new Dialog(requireContext());
        dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);
        dialog.setContentView(view);
        dialog.setCancelable(true);
        dialog.setCanceledOnTouchOutside(true);
        return dialog;
    }

    @Override
    public void onStart() {
        super.onStart();
        Dialog dialog = getDialog();
        if (dialog != null && dialog.getWindow() != null) {
            Window window = dialog.getWindow();
            window.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));
            int width = (int) (requireContext().getResources().getDisplayMetrics().widthPixels * 0.94f);
            window.setLayout(width, WindowManager.LayoutParams.WRAP_CONTENT);
        }
    }

    private void bindViews(View view) {
        btnClose = view.findViewById(R.id.btnCloseRegisterDialog);
        tilName = view.findViewById(R.id.tilRegisterName);
        tilPhone = view.findViewById(R.id.tilRegisterPhone);
        tilPassword = view.findViewById(R.id.tilRegisterPassword);
        etName = view.findViewById(R.id.etRegisterName);
        etPhone = view.findViewById(R.id.etRegisterPhone);
        etPassword = view.findViewById(R.id.etRegisterPassword);
        btnRegister = view.findViewById(R.id.btnRegister);
        tvOpenLogin = view.findViewById(R.id.tvOpenLogin);
    }

    private void setupActions() {
        btnClose.setOnClickListener(v -> dismiss());
        tvOpenLogin.setOnClickListener(v -> {
            dismiss();
            if (getActivity() instanceof RegisterDialogListener) {
                ((RegisterDialogListener) getActivity()).onOpenLoginRequested();
            }
        });
        btnRegister.setOnClickListener(v -> attemptRegister());

        TextWatcher textWatcher = new TextWatcher() {
            @Override
            public void beforeTextChanged(CharSequence s, int start, int count, int after) {
            }

            @Override
            public void onTextChanged(CharSequence s, int start, int before, int count) {
                clearErrors();
                updateRegisterButtonState();
            }

            @Override
            public void afterTextChanged(Editable s) {
            }
        };

        etName.addTextChangedListener(textWatcher);
        etPhone.addTextChangedListener(textWatcher);
        etPassword.addTextChangedListener(textWatcher);
    }

    private void attemptRegister() {
        String fullName = getText(etName);
        String phone = getText(etPhone);
        String password = getText(etPassword);
        boolean isValid = true;
        View firstInvalidField = null;

        clearErrors();

        if (!AuthValidator.isValidFullName(fullName)) {
            tilName.setError(getString(R.string.validation_name_required));
            isValid = false;
            firstInvalidField = etName;
        }

        if (!AuthValidator.isValidPhone(phone)) {
            tilPhone.setError(getString(R.string.validation_phone_required));
            isValid = false;
            if (firstInvalidField == null) {
                firstInvalidField = etPhone;
            }
        }

        if (!AuthValidator.isValidPassword(password)) {
            tilPassword.setError(getString(R.string.validation_password_register));
            isValid = false;
            if (firstInvalidField == null) {
                firstInvalidField = etPassword;
            }
        }

        if (!isValid) {
            if (firstInvalidField != null) {
                firstInvalidField.requestFocus();
            }
            return;
        }

        setLoading(true);
        authRepository.register(fullName, phone, password, new AuthRepository.AuthCallback() {
            @Override
            public void onSuccess(String token, String message) {
                if (!isAdded()) {
                    return;
                }

                String displayName = fullName.trim();
                authSessionManager.savePendingRegistration(displayName, phone);
                Toast.makeText(requireContext(), getString(R.string.register_success, displayName), Toast.LENGTH_SHORT).show();
                if (getActivity() instanceof RegisterDialogListener) {
                    ((RegisterDialogListener) getActivity()).onRegisterSuccess(displayName);
                }
                dismissAllowingStateLoss();

                if (getActivity() instanceof RegisterDialogListener) {
                    etPhone.post(() -> {
                        if (getActivity() instanceof RegisterDialogListener) {
                            ((RegisterDialogListener) getActivity()).onOpenLoginRequested();
                        }
                    });
                }
            }

            @Override
            public void onError(String message) {
                if (!isAdded()) {
                    return;
                }

                setLoading(false);
                tilPhone.setError(message);
                Toast.makeText(requireContext(), message, Toast.LENGTH_SHORT).show();
            }
        });
    }

    private void clearErrors() {
        tilName.setError(null);
        tilPhone.setError(null);
        tilPassword.setError(null);
    }

    private void updateRegisterButtonState() {
        btnRegister.setEnabled(true);
    }

    private void setLoading(boolean isLoading) {
        if (contentView != null) {
            contentView.setEnabled(!isLoading);
        }
        btnClose.setEnabled(!isLoading);
        etName.setEnabled(!isLoading);
        etPhone.setEnabled(!isLoading);
        etPassword.setEnabled(!isLoading);
        tvOpenLogin.setEnabled(!isLoading);
        btnRegister.setEnabled(!isLoading);
        btnRegister.setText(isLoading ? R.string.action_registering : R.string.action_register);
        Dialog dialog = getDialog();
        if (dialog != null) {
            dialog.setCancelable(!isLoading);
            dialog.setCanceledOnTouchOutside(!isLoading);
        }
    }

    private String getText(TextInputEditText editText) {
        return editText.getText() == null ? "" : editText.getText().toString().trim();
    }
}

package com.example.a2hauto.model;

import com.google.gson.annotations.SerializedName;
import java.util.List;

public class ApiResponse<T> {
    @SerializedName("success")
    private boolean success;
    @SerializedName("message")
    private String message;
    @SerializedName("data")
    private T data;

    public boolean isSuccess() { return success; }
    public String getMessage() { return message; }
    public T getData() { return data; }
}

package com.example.a2hauto.model;

import com.google.gson.annotations.SerializedName;
import java.util.List;

public class ApiResponse<T> {
    @SerializedName("success")
    private boolean success;
    @SerializedName("message")
    private String message;
    @SerializedName("data")
    private T data;
    @SerializedName("errors")
    private List<String> errors;
    @SerializedName("timestamp")
    private String timestamp;

    public boolean isSuccess() { return success; }
    public String getMessage() { return message; }
    public T getData() { return data; }
    public List<String> getErrors() { return errors; }
    public String getTimestamp() { return timestamp; }
}

package com.example.a2hauto.model.auth;

import com.google.gson.annotations.SerializedName;

public class LoginRequest {

    @SerializedName("phoneNumber")
    private final String phoneNumber;

    @SerializedName("password")
    private final String password;

    public LoginRequest(String phoneNumber, String password) {
        this.phoneNumber = phoneNumber;
        this.password = password;
    }
}

package com.example.a2hauto.model.auth;

import com.google.gson.annotations.SerializedName;

public class RegisterRequest {

    @SerializedName("fullName")
    private final String fullName;

    @SerializedName("phoneNumber")
    private final String phoneNumber;

    @SerializedName("password")
    private final String password;

    public RegisterRequest(String fullName, String phoneNumber, String password) {
        this.fullName = fullName;
        this.phoneNumber = phoneNumber;
        this.password = password;
    }
}
